___CSS_LOADER_EXPORT___.push([module.id, "/*\n * The collapsed stage column: a labelled strip you click to bring the stage back.\n *\n * It covers the column rather than replacing it. The stage stays mounted and merely\n * clipped — unmounting StageWrapper would take the renderer's canvas with it — so this\n * is an opaque lid over a 28px slice of live stage, not a substitute for it.\n */\n\n.pane-strip_strip_wdBkc {\n    position: absolute;\n    top: 0;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    z-index: 15;\n\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 8px;\n\n    margin: 0;\n    padding: 8px 0;\n    border: none;\n    border-left: 1px solid rgba(0, 0, 0, 0.1);\n    background: #f9f9f9;\n    color: #575e75;\n    cursor: pointer;\n    /* The whole strip is the target; 28px is already a small thing to hit. */\n    width: 100%;\n    font: inherit;\n}\n\n.pane-strip_strip_wdBkc:hover,\n.pane-strip_strip_wdBkc:focus-visible {\n    background: #f2f7ff;\n    color: #4c97ff;\n    outline: none;\n}\n\n.pane-strip_label_BA6a0 {\n    writing-mode: vertical-rl;\n    /* Bottom-to-top: the convention for a vertical label on a left-hand edge, and it\n       keeps the word upright rather than lying on its side. */\n    transform: rotate(180deg);\n    -webkit-text-orientation: mixed;\n            text-orientation: mixed;\n    font-size: 0.75rem;\n    font-weight: bold;\n    letter-spacing: 0.02em;\n    white-space: nowrap;\n    /* A long word in a narrow column must not force the strip wider. */\n    overflow: hidden;\n    text-overflow: ellipsis;\n    max-height: 100%;\n}\n\n.pane-strip_chevron_LBEge {\n    font-size: 0.85rem;\n    line-height: 1;\n    flex-shrink: 0;\n}\n", ""]);
